import { NextResponse } from 'next/server'
import type { NextRequest } from 'next/server'

// JWT verification function (you'll need to implement this based on your JWT library)
function verifyJWT(token: string): boolean {
  try {
    // Replace this with your actual JWT verification logic
    // Example using jsonwebtoken library:
    // const decoded = jwt.verify(token, process.env.JWT_SECRET!);
    // return !!decoded;

    // For now, we'll use a simple check - replace with real implementation
    return token && token.length > 10; // Basic validation
  } catch (error) {
    return false;
  }
}

export function middleware(request: NextRequest) {
  // Get the JWT token from cookies
  const token = request.cookies.get('auth-token')?.value

  // Check if the user is trying to access a protected route
  const isProtectedRoute = !request.nextUrl.pathname.startsWith('/login') &&
                          !request.nextUrl.pathname.startsWith('/api/auth') &&
                          !request.nextUrl.pathname.startsWith('/_next') &&
                          !request.nextUrl.pathname.startsWith('/favicon.ico')

  // If it's a protected route and no valid token exists, redirect to login
  if (isProtectedRoute && (!token || !verifyJWT(token))) {
    // Store the original URL to redirect back after login
    const loginUrl = new URL('/login', request.url)
    loginUrl.searchParams.set('from', request.nextUrl.pathname)

    return NextResponse.redirect(loginUrl)
  }

  // If user is on login page but already authenticated, redirect to home
  if (request.nextUrl.pathname.startsWith('/login') && token && verifyJWT(token)) {
    const from = request.nextUrl.searchParams.get('from') || '/'
    return NextResponse.redirect(new URL(from, request.url))
  }

  // Allow the request to proceed
  return NextResponse.next()
}

export const config = {
  matcher: [
    /*
     * Match all request paths except for the ones starting with:
     * - api/auth (authentication API routes)
     * - _next/static (static files)
     * - _next/image (image optimization files)
     * - favicon.ico (favicon file)
     * - public folder files (if you have any)
     */
    '/((?!api/auth|_next/static|_next/image|favicon.ico).*)',
  ],
}

