import React, { useState } from 'react';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';

interface CreatePostFormProps {
  onSubmit?: (data: { title: string; content: string }) => void;
}

export function CreatePostForm({ onSubmit }: CreatePostFormProps) {
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');

  // Check if both fields are filled
  const isFormValid = title.trim() !== '' && content.trim() !== '';

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (isFormValid && onSubmit) {
      onSubmit({
        title: title.trim(),
        content: content.trim(),
      });
    }
  };

  return (
    <Card className="w-full max-w-2xl mx-auto">
      <CardHeader>
        <CardTitle>Create New Post</CardTitle>
        <CardDescription>
          Fill in the title and content to create a new post. Both fields are required.
        </CardDescription>
      </CardHeader>
      <CardContent>
        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="space-y-2">
            <Label htmlFor="title">Title</Label>
            <Input
              id="title"
              type="text"
              placeholder="Enter post title..."
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              className="w-full"
            />
            {title.trim() === '' && (
              <p className="text-sm text-red-500">Title is required</p>
            )}
          </div>

          <div className="space-y-2">
            <Label htmlFor="content">Content</Label>
            <Textarea
              id="content"
              placeholder="Write your post content here..."
              value={content}
              onChange={(e) => setContent(e.target.value)}
              className="min-h-[200px] w-full"
            />
            {content.trim() === '' && (
              <p className="text-sm text-red-500">Content is required</p>
            )}
          </div>

          <div className="flex justify-end">
            <Button
              type="submit"
              disabled={!isFormValid}
              className="w-full sm:w-auto"
            >
              Publish Post
            </Button>
          </div>
        </form>
      </CardContent>
    </Card>
  );
}

// Example usage component
export default function CreatePostPage() {
  const handlePostSubmit = (data: { title: string; content: string }) => {
    console.log('Post submitted:', data);
    // Here you would typically send the data to your API
    alert(`Post "${data.title}" published successfully!`);
  };

  return (
    <div className="container mx-auto p-6">
      <CreatePostForm onSubmit={handlePostSubmit} />
    </div>
  );
}

// Enhanced version with loading state and better validation feedback
export function EnhancedCreatePostForm({ onSubmit }: CreatePostFormProps) {
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [touched, setTouched] = useState({
    title: false,
    content: false,
  });

  // Validation functions
  const titleError = touched.title && title.trim() === '';
  const contentError = touched.content && content.trim() === '';

  // Check if both fields are filled
  const isFormValid = title.trim() !== '' && content.trim() !== '';

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Mark all fields as touched to show validation errors
    setTouched({ title: true, content: true });

    if (!isFormValid) return;

    setIsSubmitting(true);

    try {
      if (onSubmit) {
        await onSubmit({
          title: title.trim(),
          content: content.trim(),
        });
      }
      // Reset form after successful submission
      setTitle('');
      setContent('');
      setTouched({ title: false, content: false });
    } catch (error) {
      console.error('Error submitting post:', error);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleBlur = (field: 'title' | 'content') => {
    setTouched(prev => ({ ...prev, [field]: true }));
  };

  return (
    <Card className="w-full max-w-2xl mx-auto">
      <CardHeader>
        <CardTitle>Create New Post</CardTitle>
        <CardDescription>
          Fill in the title and content to create a new post. Both fields are required.
        </CardDescription>
      </CardHeader>
      <CardContent>
        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="space-y-2">
            <Label htmlFor="title">Title</Label>
            <Input
              id="title"
              type="text"
              placeholder="Enter post title..."
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              onBlur={() => handleBlur('title')}
              className={`w-full ${titleError ? 'border-red-500' : ''}`}
              disabled={isSubmitting}
            />
            {titleError && (
              <p className="text-sm text-red-500">Title is required</p>
            )}
          </div>

          <div className="space-y-2">
            <Label htmlFor="content">Content</Label>
            <Textarea
              id="content"
              placeholder="Write your post content here..."
              value={content}
              onChange={(e) => setContent(e.target.value)}
              onBlur={() => handleBlur('content')}
              className={`min-h-[200px] w-full ${contentError ? 'border-red-500' : ''}`}
              disabled={isSubmitting}
            />
            {contentError && (
              <p className="text-sm text-red-500">Content is required</p>
            )}
          </div>

          <div className="flex justify-end space-x-4">
            <Button
              type="button"
              variant="outline"
              onClick={() => {
                setTitle('');
                setContent('');
                setTouched({ title: false, content: false });
              }}
              disabled={isSubmitting}
            >
              Clear
            </Button>
            <Button
              type="submit"
              disabled={!isFormValid || isSubmitting}
              className="min-w-[120px]"
            >
              {isSubmitting ? (
                <>
                  <span className="animate-spin mr-2">⟳</span>
                  Publishing...
                </>
              ) : (
                'Publish Post'
              )}
            </Button>
          </div>
        </form>
      </CardContent>
    </Card>
  );
}

// Usage example with toast notifications
import { toast } from 'sonner';

export function CreatePostWithToast() {
  const handlePostSubmit = async (data: { title: string; content: string }) => {
    // Simulate API call
    await new Promise(resolve => setTimeout(resolve, 2000));

    toast.success(`Post "${data.title}" published successfully!`);
    console.log('Post submitted:', data);
  };

  return (
    <div className="container mx-auto p-6">
      <EnhancedCreatePostForm onSubmit={handlePostSubmit} />
    </div>
  );
}

// Custom hook for form state management
function useCreatePostForm() {
  const [formData, setFormData] = useState({
    title: '',
    content: '',
  });
  const [touched, setTouched] = useState({
    title: false,
    content: false,
  });
  const [isSubmitting, setIsSubmitting] = useState(false);

  const titleError = touched.title && formData.title.trim() === '';
  const contentError = touched.content && formData.content.trim() === '';
  const isFormValid = formData.title.trim() !== '' && formData.content.trim() !== '';

  const updateField = (field: 'title' | 'content', value: string) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const markFieldTouched = (field: 'title' | 'content') => {
    setTouched(prev => ({ ...prev, [field]: true }));
  };

  const resetForm = () => {
    setFormData({ title: '', content: '' });
    setTouched({ title: false, content: false });
  };

  return {
    formData,
    touched,
    isSubmitting,
    titleError,
    contentError,
    isFormValid,
    updateField,
    markFieldTouched,
    setIsSubmitting,
    resetForm,
  };
}

// Hook-based component
export function HookBasedCreatePostForm({ onSubmit }: CreatePostFormProps) {
  const {
    formData,
    touched,
    isSubmitting,
    titleError,
    contentError,
    isFormValid,
    updateField,
    markFieldTouched,
    setIsSubmitting,
    resetForm,
  } = useCreatePostForm();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Mark all fields as touched
    markFieldTouched('title');
    markFieldTouched('content');

    if (!isFormValid) return;

    setIsSubmitting(true);

    try {
      if (onSubmit) {
        await onSubmit({
          title: formData.title.trim(),
          content: formData.content.trim(),
        });
      }
      resetForm();
    } catch (error) {
      console.error('Error submitting post:', error);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Card className="w-full max-w-2xl mx-auto">
      <CardHeader>
        <CardTitle>Create New Post</CardTitle>
        <CardDescription>
          Fill in the title and content to create a new post. Both fields are required.
        </CardDescription>
      </CardHeader>
      <CardContent>
        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="space-y-2">
            <Label htmlFor="title">Title</Label>
            <Input
              id="title"
              type="text"
              placeholder="Enter post title..."
              value={formData.title}
              onChange={(e) => updateField('title', e.target.value)}
              onBlur={() => markFieldTouched('title')}
              className={`w-full ${titleError ? 'border-red-500' : ''}`}
              disabled={isSubmitting}
            />
            {titleError && (
              <p className="text-sm text-red-500">Title is required</p>
            )}
          </div>

          <div className="space-y-2">
            <Label htmlFor="content">Content</Label>
            <Textarea
              id="content"
              placeholder="Write your post content here..."
              value={formData.content}
              onChange={(e) => updateField('content', e.target.value)}
              onBlur={() => markFieldTouched('content')}
              className={`min-h-[200px] w-full ${contentError ? 'border-red-500' : ''}`}
              disabled={isSubmitting}
            />
            {contentError && (
              <p className="text-sm text-red-500">Content is required</p>
            )}
          </div>

          <div className="flex justify-between items-center">
            <div className="text-sm text-muted-foreground">
              {isFormValid ? '✓ Form is ready to submit' : 'Please fill in all required fields'}
            </div>
            <div className="flex space-x-4">
              <Button
                type="button"
                variant="outline"
                onClick={resetForm}
                disabled={isSubmitting}
              >
                Clear
              </Button>
              <Button
                type="submit"
                disabled={!isFormValid || isSubmitting}
                className="min-w-[120px]"
              >
                {isSubmitting ? (
                  <>
                    <span className="animate-spin mr-2">⟳</span>
                    Publishing...
                  </>
                ) : (
                  'Publish Post'
                )}
              </Button>
            </div>
          </div>
        </form>
      </CardContent>
    </Card>
  );
}

